result.command:
PDF='/tmp/release/packet.pdf'
TEMPLATE='/tmp/release/release_packet.pdf'
[ -s "$PDF" ] && [ -s "$TEMPLATE" ] && [ "$(head -c 5 "$PDF" 2>/dev/null)" = '%PDF-' ] || { echo invalid; exit 0; }
command -v pdftotext >/dev/null 2>&1 && command -v pdfinfo >/dev/null 2>&1 || { echo missing; exit 0; }
OUT_INFO=$(pdfinfo "$PDF" 2>/dev/null) || { echo invalid; exit 0; }
TEMPLATE_INFO=$(pdfinfo "$TEMPLATE" 2>/dev/null) || { echo invalid; exit 0; }
info_value() { printf '%s\n' "$1" | awk -F: -v key="$2" '$1 == key {sub(/^[[:space:]]+/, "", $2); print $2; exit}'; }
for KEY in Pages 'Page size' 'Page rot'; do [ "$(info_value "$OUT_INFO" "$KEY")" = "$(info_value "$TEMPLATE_INFO" "$KEY")" ] || { echo template_mismatch; exit 0; }; done
TMP=$(mktemp)
pdftotext "$PDF" "$TMP" 2>/dev/null && test -s "$TMP" || { rm -f "$TMP"; echo invalid; exit 0; }
printf '%s\n' template_fidelity_ok
cat "$TMP"
rm -f "$TMP"
